const sqlite3 = require('sqlite3').verbose();

const filtro = $input.first().json.filtro || 'scadenza_settimana';

const oggi = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const oggiStr = `${oggi.getFullYear()}-${String(oggi.getMonth()+1).padStart(2,'0')}-${String(oggi.getDate()).padStart(2,'0')}`;
const fraSettimana = new Date(oggi.getTime() + 7 * 24 * 60 * 60 * 1000);
const fraSettimanaStr = `${fraSettimana.getFullYear()}-${String(fraSettimana.getMonth()+1).padStart(2,'0')}-${String(fraSettimana.getDate()).padStart(2,'0')}`;

let query = '';
let params = [];

if (filtro === 'scadenza_settimana') {
  query = `SELECT * FROM task WHERE stato = 'aperto' AND scadenza IS NOT NULL AND date(scadenza) <= ? ORDER BY scadenza ASC`;
  params = [fraSettimanaStr];
} else if (filtro === 'urgenti') {
  query = `SELECT * FROM task WHERE stato = 'aperto' AND priorita = 'alta' ORDER BY scadenza ASC`;
} else if (filtro === 'arretrati') {
  query = `SELECT * FROM task WHERE stato = 'aperto' AND scadenza IS NOT NULL AND date(scadenza) < ? ORDER BY scadenza ASC`;
  params = [oggiStr];
} else {
  query = `SELECT * FROM task WHERE stato = 'aperto' ORDER BY scadenza ASC`;
}

const tasks = await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.all(query, params, function(err, rows) {
    db.close();
    if (err) reject(err);
    else resolve(rows);
  });
});

if (tasks.length === 0) {
  return [{ json: { output: `Nessun task trovato per filtro: ${filtro}.` } }];
}

const lista = tasks.map(t => {
  const scad = t.scadenza ? `, scadenza ${t.scadenza.slice(0,10)}` : ', nessuna scadenza';
  const arretrato = t.scadenza && t.scadenza.slice(0,10) < oggiStr ? ' [ARRETRATO]' : '';
  return `ID ${t.id}: "${t.descrizione}" - priorità ${t.priorita}${scad}${arretrato}`;
}).join('\n');

return [{ json: { 
  output: `Trovati ${tasks.length} task (filtro: ${filtro}):\n${lista}`
} }];
